test('missing data is reported, never invented', () => {
  const noTeam = { id: 'a', name: 'Free Agent', pos: 'WR', team: 'FA', bye: 0, avail: 1, cv: 0.4, mu: { rec: 5 } };
  const r1 = projectFast(noTeam, { pack: VIEW, cfg: FULL });
  assert.equal(r1.mean, 0);
  assert.equal(r1.games, 0);
  assert.ok(/schedule/i.test(r1.note));

  const noMu = { id: 'b', name: 'No Projection', pos: 'WR', team: 'KC', bye: 5, avail: 1, cv: 0.4 };
  const r2 = projectFast(noMu, { pack: VIEW, cfg: FULL });
  assert.equal(r2.mean, 0);
  assert.ok(/manual/i.test(r2.note), 'the app must offer manual entry, not a fabricated zero');

  const noKicking = { id: 'c', name: 'No Kicker Data', pos: 'K', team: 'KC', bye: 5, avail: 1, cv: 0.4 };
  assert.ok(projectFast(noKicking, { pack: VIEW, cfg: FULL }).note.length > 0);

  const noDst = { id: 'd', name: 'No DST Data', pos: 'DST', team: 'KC', bye: 5, avail: 1, cv: 0.5 };
  assert.ok(projectFast(noDst, { pack: VIEW, cfg: FULL }).note.length > 0);

  for (const bad of [null, undefined, 42, 'x']) {
    const r = projectFast(bad, { pack: VIEW, cfg: FULL });
    assert.equal(r.mean, 0);
    assert.ok(r.note.length > 0);
  }
  // No pack at all: nothing throws, nothing is invented.
  const r3 = projectFast(topAt('WR', 1)[0].player, { cfg: FULL });
  assert.equal(r3.mean, 0);
});

