test('nothing in the pack is ever mutated', () => {
  const before = JSON.stringify(PACK);
  for (const p of VIEW.players) {
    projectFast(p, { pack: VIEW, cfg: FULL });
    weeklyMu(p, 1, VIEW);
    historicalPPG(p, HALF, VIEW);
  }
  seasonTotal(VIEW.players[0], { pack: PACK, cfg: HALF });
  restOfSeason(VIEW.players[1], { pack: PACK, cfg: FULL, fromWeek: 9 });
  assert.equal(JSON.stringify(PACK), before, 'the pack changed under a projection pass');
});

test('projections do not alias each other or the pack', () => {
  const wr = topAt('WR', 1)[0].player;
  const a = seasonTotal(wr, { pack: VIEW, cfg: FULL });
  const b = seasonTotal(wr, { pack: VIEW, cfg: FULL });
  assert.notEqual(a, b);
  assert.notEqual(a.perWeek, b.perWeek);
  assert.equal(a.mean, b.mean);
  a.perWeek[0].mean = -1;
  assert.notEqual(b.perWeek[0].mean, -1);
  assert.equal(seasonTotal(wr, { pack: VIEW, cfg: FULL }).mean, b.mean);
});

test('results are deterministic and independent of the order players are projected in', () => {
  const sample = VIEW.players.slice(0, 200);
  const forward = sample.map((p) => projectFast(p, { pack: VIEW, cfg: FULL, perWeek: false }).mean);
  const backward = sample.slice().reverse()
    .map((p) => projectFast(p, { pack: VIEW, cfg: FULL, perWeek: false }).mean)
    .reverse();
  assert.deepEqual(backward, forward);
});

