test('project equals projectFast when no simulation engine is wired in', () => {
  assert.equal(simEngine(), null);
  for (const pos of ['QB', 'RB', 'WR', 'TE', 'K', 'DST']) {
    for (const { player } of topAt(pos, 3)) {
      const a = project(player, { pack: VIEW, cfg: FULL });
      const b = projectFast(player, { pack: VIEW, cfg: FULL });
      assert.equal(a.method, 'closed-form');
      assert.deepEqual(
        { m: a.mean, s: a.sd, l: a.p10, x: a.p90 },
        { m: b.mean, s: b.sd, l: b.p10, x: b.p90 },
      );
    }
  }
});

test('a wired-in sim engine takes over, and its input carries what it needs', () => {
  const wr = topAt('WR', 1)[0].player;
  let seen = null;
  const engine = {
    simSeason(spec) {
      seen = spec;
      return { mean: 300, sd: 50 };
    },
  };

  const r = project(wr, { pack: VIEW, cfg: FULL, sim: engine, iters: 777, seed: 42 });
  assert.equal(r.method, 'sim');
  assert.equal(r.mean, 300);
  assert.equal(r.sd, 50);
  assert.ok(r.p10 < 300 && r.p90 > 300);
  assert.ok(r.closedForm && Number.isFinite(r.closedForm.mean),
    'the closed form must stay visible next to the simulated answer');

  assert.equal(seen.player, wr);
  assert.equal(seen.cfg, FULL);
  assert.equal(seen.pack, PACK);
  assert.equal(seen.view, VIEW);
  assert.equal(seen.iters, 777);
  assert.equal(seen.seed, 42);
  assert.ok(Array.isArray(seen.weeks) && seen.weeks.length > 0);
  assert.deepEqual(seen.weeklyMu(wr, seen.weeks[0]), weeklyMu(wr, seen.weeks[0], PACK));
});

test('a sim engine returning samples is summarized correctly', () => {
  const wr = topAt('WR', 1)[0].player;
  const samples = [];
  for (let i = 0; i < 1001; i++) samples.push(100 + i * 0.2); // 100 .. 300, uniform
  const r = project(wr, { pack: VIEW, cfg: FULL, sim: () => samples });
  assert.equal(r.method, 'sim');
  assert.ok(close(r.mean, 200, 1e-6));
  assert.ok(close(r.p50, 200, 1e-6));
  assert.ok(close(r.p10, 120, 1e-6));
  assert.ok(close(r.p90, 280, 1e-6));
  assert.ok(r.sd > 0);
});

test('an untrustworthy sim engine is refused, and the refusal is reported', () => {
  const wr = topAt('WR', 1)[0].player;
  const good = projectFast(wr, { pack: VIEW, cfg: FULL });

  const cases = [
    ['throws', () => { throw new Error('boom'); }],
    ['returns nothing', () => undefined],
    ['returns junk', () => ({ hello: 'world' })],
    ['returns NaN', () => ({ mean: NaN, sd: NaN })],
    ['returns too few samples', () => [1]],
  ];
  for (const [label, sim] of cases) {
    const r = project(wr, { pack: VIEW, cfg: FULL, sim });
    assert.equal(r.method, 'closed-form', `${label}: should have fallen back`);
    assert.equal(r.mean, good.mean, `${label}: fallback must be the closed form`);
    assert.ok(r.note.length > 0, `${label}: the fallback must be explained`);
  }
});

test('an engine exposing simPlayerWeek is driven week by week and summed', () => {
  const wr = topAt('WR', 1)[0].player;
  const calls = [];
  const N = 500;
  const engine = {
    makeRng(seed) { const r = () => 0.5; r.seed = seed; return r; },
    simPlayerWeek(player, week, cfg, pack, rng, iters) {
      calls.push({ player, week, cfg, pack, rng, iters });
      const samples = new Float64Array(N);
      // Week w contributes exactly w points in every draw, so the total is predictable.
      for (let i = 0; i < N; i++) samples[i] = week;
      return { mean: week, sd: 0, samples };
    },
  };

  const weeks = scheduledWeeks(wr.team).slice(0, 4);
  const r = project(wr, { pack: VIEW, cfg: FULL, sim: engine, weeks, iters: 321, seed: 7 });

  assert.equal(r.method, 'sim');
  assert.equal(calls.length, weeks.length, 'every requested week must be drawn');
  assert.deepEqual(calls.map((c) => c.week), weeks);
  assert.equal(calls[0].player, wr);
  assert.equal(calls[0].cfg, FULL);
  assert.equal(calls[0].pack, PACK);
  assert.equal(calls[0].iters, 321);
  assert.equal(calls[0].rng.seed, 7, 'the engine RNG must be seeded from opts.seed');
  assert.ok(calls.every((c) => c.rng === calls[0].rng), 'one RNG stream across the weeks');

  const expected = weeks.reduce((a, w) => a + w, 0);
  assert.ok(close(r.mean, expected, 1e-6), `${r.mean} != ${expected}`);
  assert.equal(r.sd, 0);
  assert.ok(Number.isFinite(r.closedForm.mean));

  // simMode 'season' skips the per-week path entirely.
  calls.length = 0;
  const seasonEngine = { ...engine, simSeason: () => ({ mean: 9, sd: 1 }) };
  const r2 = project(wr, { pack: VIEW, cfg: FULL, sim: seasonEngine, weeks, simMode: 'season' });
  assert.equal(r2.mean, 9);
  assert.equal(calls.length, 0);
});

test('a per-week engine that misbehaves is refused too', () => {
  const wr = topAt('WR', 1)[0].player;
  const good = projectFast(wr, { pack: VIEW, cfg: FULL });
  const weeks = scheduledWeeks(wr.team).slice(0, 3);

  const cases = [
    ['no samples', { simPlayerWeek: () => ({ mean: 10, sd: 2 }) }],
    ['ragged samples', {
      simPlayerWeek: (p, w) => ({ samples: new Float64Array(w === weeks[0] ? 10 : 11) }),
    }],
    ['NaN samples', { simPlayerWeek: () => ({ samples: [NaN, NaN, NaN] }) }],
    ['throws', { simPlayerWeek: () => { throw new Error('nope'); } }],
    ['returns nothing', { simPlayerWeek: () => null }],
  ];
  for (const [label, sim] of cases) {
    const r = project(wr, { pack: VIEW, cfg: FULL, sim, weeks });
    assert.equal(r.method, 'closed-form', `${label}: should have fallen back`);
    assert.ok(r.note.length > 0, `${label}: the fallback must be explained`);
    assert.ok(Number.isFinite(r.mean));
  }
  assert.ok(good.mean > 0);
});

test('the real sim.js, when present, plugs straight in', async () => {
  let sim = null;
  try {
    sim = await import('../app/js/sim.js');
  } catch {
    return; // sim.js is not built yet; project() is the closed form and that is contractual.
  }
  if (!sim || typeof sim.simPlayerWeek !== 'function') return;

  const wr = topAt('WR', 1)[0].player;
  const weeks = scheduledWeeks(wr.team).slice(0, 5);
  const closed = projectFast(wr, { pack: VIEW, cfg: FULL, weeks });
  const r = project(wr, { pack: VIEW, cfg: FULL, sim, weeks, iters: 600, seed: 11 });

  // Either it was adopted, or it was refused and said so. Both are correct outcomes; what is
  // NOT allowed is a silently wrong number.
  assert.ok(Number.isFinite(r.mean));
  assert.ok(r.p10 <= r.p50 + EPS && r.p50 <= r.p90 + EPS);
  if (r.method === 'sim') {
    assert.ok(r.mean > 0, 'a simulated elite WR should score');
    // The closed form and the simulation are two roads to the same mean. They will not agree
    // exactly (thresholds and skew differ), but a large gap means one of them is wrong.
    const rel = Math.abs(r.mean - closed.mean) / closed.mean;
    assert.ok(rel < 0.3,
      `sim (${r.mean}) and closed form (${closed.mean}) disagree by ${(rel * 100).toFixed(0)}%`);
    assert.ok(r.sd > 0);
    // Reproducible: the same seed must give the same answer.
    const again = project(wr, { pack: VIEW, cfg: FULL, sim, weeks, iters: 600, seed: 11 });
    assert.equal(again.mean, r.mean);
    assert.equal(again.p90, r.p90);
  } else {
    assert.equal(r.method, 'closed-form');
    assert.ok(r.note.length > 0);
  }
});

test('the closed form agrees with the Monte Carlo it stands in for', async () => {
  let sim = null;
  try {
    sim = await import('../app/js/sim.js');
  } catch {
    return;
  }
  if (!sim || typeof sim.simPlayerWeek !== 'function') return;

  // The whole point of a closed form is that it is the same answer, cheaply. Compare the
  // full-season mean and (with the season-level role-risk term switched off, which the sim
  // does not model) the spread, across the board and down the depth chart.
  const picks = [];
  for (const pos of ['QB', 'RB', 'WR', 'TE', 'K', 'DST']) {
    const ranked = topAt(pos, 21).map((x) => x.player);
    for (const i of [0, 8, 20]) if (ranked[i]) picks.push(ranked[i]);
  }

  let compared = 0;
  for (const p of picks) {
    if (!PACK.schedule[p.team]) continue;
    const weeks = scheduledWeeks(p.team);
    const closed = projectFast(p, { pack: VIEW, cfg: FULL, weeks, perWeek: false, meanUncertainty: 0 });
    const s = project(p, { pack: VIEW, cfg: FULL, weeks, sim, iters: 4000, seed: 3 });
    if (s.method !== 'sim' || !(closed.mean > 0)) continue;
    compared++;

    const relMean = Math.abs(s.mean - closed.mean) / closed.mean;
    assert.ok(relMean < 0.05,
      `${p.name}: closed form ${closed.mean} vs simulation ${s.mean} (${(relMean * 100).toFixed(1)}%)`);

    const ratio = closed.sd / s.sd;
    assert.ok(ratio > 0.6 && ratio < 1.5,
      `${p.name}: closed-form sd ${closed.sd} vs simulated ${s.sd} (ratio ${ratio.toFixed(2)})`);
  }
  assert.ok(compared >= 12, `expected to compare many players, compared ${compared}`);
});

test('useSim registers and unregisters a default engine', () => {
  const wr = topAt('WR', 1)[0].player;
  try {
    useSim({ simSeason: () => ({ mean: 111, sd: 11 }) });
    assert.ok(simEngine());
    assert.equal(project(wr, { pack: VIEW, cfg: FULL }).mean, 111);
    // An explicit `sim: false` opts one call back out.
    assert.equal(project(wr, { pack: VIEW, cfg: FULL, sim: false }).method, 'closed-form');
  } finally {
    useSim(null);
  }
  assert.equal(simEngine(), null);
  assert.equal(project(wr, { pack: VIEW, cfg: FULL }).method, 'closed-form');
});

/* ------------------------------------------------- the model says sane things */

test('the projected board looks like a football season, not a random number generator', () => {
  const wr1 = topAt('WR', 1)[0];
  const rb1 = topAt('RB', 1)[0];
  const qb1 = topAt('QB', 1)[0];
  const te1 = topAt('TE', 1)[0];
  const k1 = topAt('K', 1)[0];
  const d1 = topAt('DST', 1)[0];

  // Full PPR, 17-game seasons: an elite skill player lands in the 250-420 range.
  for (const top of [wr1, rb1, qb1]) {
    assert.ok(top.proj.mean > 200 && top.proj.mean < 450,
      `${top.player.name} projects ${top.proj.mean}, which is not a real season`);
  }
  assert.ok(te1.proj.mean > 100 && te1.proj.mean < 350);
  // Kickers and defenses live in a much narrower band.
  assert.ok(k1.proj.mean > 80 && k1.proj.mean < 220, `K1 ${k1.proj.mean}`);
  assert.ok(d1.proj.mean > 60 && d1.proj.mean < 220, `DST1 ${d1.proj.mean}`);

  // 4-point passing TDs compress quarterbacks: QB1 to QB12 is a smaller gap, relatively,
  // than WR1 to WR12. That is contract section 9, and the app is supposed to price it.
  const qbs = topAt('QB', 12).map((x) => x.proj.mean);
  const wrs = topAt('WR', 12).map((x) => x.proj.mean);
  const qbGap = (qbs[0] - qbs[11]) / qbs[0];
  const wrGap = (wrs[0] - wrs[11]) / wrs[0];
  assert.ok(qbGap < wrGap,
    `QB compression: QB1->QB12 drop ${qbGap} should be flatter than WR1->WR12 ${wrGap}`);
});

test('a season band is wide enough to be honest and tight enough to be useful', () => {
  for (const pos of ['QB', 'RB', 'WR', 'TE']) {
    for (const { player, proj } of topAt(pos, 6)) {
      const rel = proj.sd / proj.mean;
      assert.ok(rel > 0.08 && rel < 0.8,
        `${player.name}: season band is ${(rel * 100).toFixed(0)}% of the mean`);
      assert.ok(proj.p10 > 0, `${player.name}: an elite player's floor should not be zero`);
      assert.ok(proj.p90 > proj.mean);
    }
  }
});

test('touchdown dependence shows up as volatility, receptions as stability', () => {
  // Two synthetic receivers, same team, same week, same usage CV. One earns his points on
  // reception volume, the other on touchdowns. Full PPR is supposed to make that difference
  // legible, so the touchdown-dependent one must carry the wider band per point of mean.
  const team = 'KC';
  const week = scheduledWeeks(team)[0];
  const base = { pos: 'WR', team, bye: VIEW.byeOf(team), avail: 1, cv: 0.35 };
  const volume = { ...base, id: 'v', name: 'Volume', mu: { tgt: 12, rec: 9, reyd: 96, retd: 0.15 } };
  const tdDep = { ...base, id: 't', name: 'Touchdowns', mu: { tgt: 5, rec: 3, reyd: 40, retd: 1.6 } };

  const a = weeklyProjection(volume, week, { pack: VIEW, cfg: FULL });
  const b = weeklyProjection(tdDep, week, { pack: VIEW, cfg: FULL });
  assert.ok(a.mean > 0 && b.mean > 0);
  assert.ok((b.sd / b.mean) > (a.sd / a.mean) * 1.3,
    'the touchdown-dependent receiver must be the volatile one: '
    + `${(b.sd / b.mean).toFixed(3)} vs ${(a.sd / a.mean).toFixed(3)}`);

  // And in standard scoring the volume receiver loses far more of his value than the
  // touchdown one does. That is the reception share of value, contract section 9.
  const std = PRESETS.standard;
  const aStd = weeklyProjection(volume, week, { pack: VIEW, cfg: std });
  const bStd = weeklyProjection(tdDep, week, { pack: VIEW, cfg: std });
  assert.ok((a.mean - aStd.mean) / a.mean > (b.mean - bStd.mean) / b.mean * 1.5,
    'the volume receiver is the one full PPR is paying for');
});
